// Sending webmentions (v0.17.0): the hook that tells every page a post links to that it did, and tells them again when
// the post changes or leaves the site, so their copy of the mention follows. The receiving side is the mentions group.
//
// Every address it fetches comes from a stranger's page, so each one is checked before it is asked, and again at every
// redirect: http or https only, never a local, loopback, private or link-local host. Nothing here parses HTML with a DOM
// (a Worker has HTMLRewriter, Node has neither); a small tag scanner over the text finds what it needs.

import type { PublishHook } from "./hooks.js";
import type { SiteApiStore } from "./store.js";

const MAX_REDIRECTS = 5;
const TIMEOUT_MS = 5000;
const MAX_BYTES = 1024 * 1024;
// A hook runs in waitUntil, which a Worker gives about 30 seconds: every target is sent at once, and all of them stop
// at BUDGET_MS, so the targets are always stored. A post linking to more than MAX_TARGETS pages tells the first ones.
const BUDGET_MS = 20_000;
const MAX_TARGETS = 100;

/** True for an address the hook may fetch: http or https, and a host that is neither local nor private. */
export function safeTarget(address: string | URL): boolean {
  let url: URL;
  try {
    url = new URL(address);
  } catch {
    return false;
  }
  if (url.protocol !== "https:" && url.protocol !== "http:") return false;
  const host = url.hostname.toLowerCase().replace(/^\[|\]$/g, "").replace(/\.$/, "");
  if (host === "localhost" || host.endsWith(".localhost") || host === "local" || host.endsWith(".local")) return false;
  if (host.includes(":")) return safeIPv6(host);
  // The URL parser already turned every IPv4 spelling (decimal, hex, short) into dotted quads.
  if (/^\d+\.\d+\.\d+\.\d+$/.test(host)) return safeIPv4(host.split(".").map(Number));
  return host.includes(".");
}

function safeIPv4([a, b, c]: number[]): boolean {
  if (a === 0 || a === 10 || a === 127 || a! >= 224) return false;
  if (a === 100 && b! >= 64 && b! <= 127) return false;
  if (a === 169 && b === 254) return false;
  if (a === 172 && b! >= 16 && b! <= 31) return false;
  if (a === 192 && (b === 168 || (b === 0 && (c === 0 || c === 2)))) return false;
  // Benchmarking (198.18.0.0/15) and the documentation ranges.
  if ((a === 198 && (b === 18 || b === 19 || (b === 51 && c === 100))) || (a === 203 && b === 0 && c === 113)) return false;
  return true;
}

/** The eight 16-bit groups of an IPv6 address as the URL parser writes it (hex, `::` for the longest zero run). */
function groups(host: string): number[] {
  const [head, tail] = host.split("::") as [string, string | undefined];
  const part = (text: string | undefined) => (text ? text.split(":").map((g) => parseInt(g, 16)) : []);
  const [first, last] = [part(head), part(tail)];
  return [...first, ...Array(8 - first.length - last.length).fill(0), ...last];
}

function safeIPv6(host: string): boolean {
  const g = groups(host);
  const v4 = (hi: number, lo: number) => safeIPv4([hi >> 8, hi & 255, lo >> 8, lo & 255]);
  const zero = (from: number, to: number) => g.slice(from, to).every((x) => x === 0);
  // An IPv4 address carried inside IPv6 is judged as that address: compatible (::a.b.c.d, which covers :: and ::1),
  // mapped (::ffff:a.b.c.d), translated (::ffff:0:a.b.c.d), NAT64 (64:ff9b::a.b.c.d) and 6to4 (2002:aabb:ccdd::).
  if (zero(0, 6) || (zero(0, 5) && g[5] === 0xffff) || (zero(0, 4) && g[4] === 0xffff && g[5] === 0)) return v4(g[6]!, g[7]!);
  if (g[0] === 0x64 && g[1] === 0xff9b && zero(2, 6)) return v4(g[6]!, g[7]!);
  if (g[0] === 0x2002) return v4(g[1]!, g[2]!);
  // NAT64 local use (64:ff9b:1::/48), discard (100::/64), Teredo (2001::/32, which hides its IPv4) and documentation (2001:db8::/32).
  if ((g[0] === 0x64 && g[1] === 0xff9b) || (g[0] === 0x100 && zero(1, 4)) || (g[0] === 0x2001 && (g[1] === 0 || g[1] === 0xdb8))) return false;
  // fc00::/7 unique local, fe80::/10 link-local, fec0::/10 site-local, ff00::/8 multicast.
  const first = g[0]!;
  return !((first & 0xfe00) === 0xfc00 || (first & 0xff80) === 0xfe80 || (first & 0xff00) === 0xff00);
}

type Tag = { name: string; attrs: string; start: number; end: number; closing: boolean };

function* tags(html: string): Generator<Tag> {
  const pattern = /<(\/?)([a-zA-Z][\w-]*)\b((?:[^>"']|"[^"]*"|'[^']*')*)>/g;
  for (let m = pattern.exec(html); m; m = pattern.exec(html)) {
    yield { name: m[2]!.toLowerCase(), attrs: m[3]!, start: m.index, end: m.index + m[0].length, closing: m[1] === "/" };
  }
}

function attr(attrs: string, name: string): string | null {
  const m = new RegExp(`(?:^|\\s)${name}\\s*=\\s*(?:"([^"]*)"|'([^']*)'|([^\\s"'>]+))`, "i").exec(attrs);
  if (!m) return null;
  return (m[1] ?? m[2] ?? m[3]!).replace(/&(amp|quot|#39|lt|gt);/g, (_, e: string) => ({ amp: "&", quot: '"', "#39": "'", lt: "<", gt: ">" })[e]!);
}

const words = (value: string | null) => (value ?? "").toLowerCase().split(/\s+/).filter(Boolean);

/** The page without what is never read for links: comments, scripts, styles and templates. */
const unread = (html: string) => html.replace(/<!--[\s\S]*?-->/g, "").replace(/<(script|style|template)\b[\s\S]*?<\/\1\s*>/gi, "");

/** The inner HTML of the first element `found` picks, from its start tag to its matching close; null when none. */
function region(html: string, found: (tag: Tag) => boolean, from = 0, to = html.length): { start: number; end: number } | null {
  let open: Tag | null = null;
  let depth = 0;
  for (const tag of tags(html.slice(0, to))) {
    if (tag.start < from) continue;
    if (!open) {
      if (!tag.closing && found(tag)) [open, depth] = [tag, 1];
      continue;
    }
    if (tag.name !== open.name) continue;
    depth += tag.closing ? -1 : 1;
    if (depth === 0) return { start: open.end, end: tag.start };
  }
  return open ? { start: open.end, end: to } : null;
}

/**
 * The post's outbound links: every http(s) `<a href>` inside the first `.h-entry .e-content`, or else the first
 * `<article>`, or else `<main>`, resolved against the page, without fragments, in order, each once. Links on the page's
 * own origin are left out: they are the site's own. Comments, scripts and styles are never read.
 */
export function outboundLinks(html: string, pageUrl: string): string[] {
  const text = unread(html);
  const entry = region(text, (t) => words(attr(t.attrs, "class")).includes("h-entry"));
  const area =
    (entry && region(text, (t) => words(attr(t.attrs, "class")).includes("e-content"), entry.start, entry.end)) ??
    region(text, (t) => t.name === "article") ??
    region(text, (t) => t.name === "main");
  if (!area) return [];
  const origin = new URL(pageUrl).origin;
  const links = new Set<string>();
  for (const tag of tags(text.slice(area.start, area.end))) {
    if (tag.closing || tag.name !== "a") continue;
    const href = attr(tag.attrs, "href");
    if (!href) continue;
    let url: URL;
    try {
      url = new URL(href, pageUrl);
    } catch {
      continue;
    }
    url.hash = "";
    if ((url.protocol === "https:" || url.protocol === "http:") && url.origin !== origin) links.add(url.href);
  }
  return [...links];
}

/** The webmention endpoint a page names: its HTTP Link header first, then the first `<link>` or `<a>` with rel webmention. */
export function endpointOf(linkHeader: string | null, html: string, pageUrl: string): string | null {
  for (const part of (linkHeader ?? "").split(/,(?=\s*<)/)) {
    const m = /<([^>]*)>(.*)/.exec(part);
    const rel = m && /;\s*rel\s*=\s*(?:"([^"]*)"|([^\s;,]+))/i.exec(m[2]!);
    if (m && rel && words(rel[1] ?? rel[2]!).includes("webmention")) return resolve(m[1]!, pageUrl);
  }
  for (const tag of tags(unread(html))) {
    if (tag.closing || (tag.name !== "link" && tag.name !== "a")) continue;
    const href = attr(tag.attrs, "href");
    if (href !== null && words(attr(tag.attrs, "rel")).includes("webmention")) return resolve(href, pageUrl);
  }
  return null;
}

function resolve(href: string, base: string): string | null {
  try {
    return new URL(href, base).href;
  } catch {
    return null;
  }
}

/** A GET that checks every address on its way, follows at most MAX_REDIRECTS, and reads at most MAX_BYTES of HTML. */
async function getPage(doFetch: typeof fetch, address: string, userAgent: string, deadline: AbortSignal): Promise<{ url: string; link: string | null; html: string }> {
  let url = address;
  for (let hop = 0; ; hop++) {
    if (!safeTarget(url)) throw new Error(`refused address ${url}`);
    const response = await doFetch(url, { redirect: "manual", headers: { "user-agent": userAgent, accept: "text/html" }, signal: limit(deadline) });
    const location = response.headers.get("location");
    if (response.status >= 300 && response.status < 400 && location) {
      await response.body?.cancel().catch(() => {});
      if (hop >= MAX_REDIRECTS) throw new Error(`more than ${MAX_REDIRECTS} redirects from ${address}`);
      url = new URL(location, url).href;
      continue;
    }
    if (!response.ok) {
      await response.body?.cancel().catch(() => {});
      throw new Error(`${url} answered ${response.status}`);
    }
    const html = /html/i.test(response.headers.get("content-type") ?? "") ? await readText(response) : "";
    return { url, link: response.headers.get("link"), html };
  }
}

/** Each fetch's own timeout, cut short by the whole run's deadline. */
const limit = (deadline: AbortSignal) => AbortSignal.any([AbortSignal.timeout(TIMEOUT_MS), deadline]);

async function readText(response: Response): Promise<string> {
  if (!response.body) return "";
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let text = "";
  let total = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    const kept = value.subarray(0, MAX_BYTES - total);
    total += kept.byteLength;
    text += decoder.decode(kept, { stream: true });
    if (total >= MAX_BYTES) {
      await reader.cancel().catch(() => {});
      break;
    }
  }
  return text + decoder.decode();
}

/** The store the hook keeps each page's sent targets in: any SiteApiStore. */
type TargetStore = Pick<SiteApiStore, "webmentionTargets" | "putWebmentionTargets">;

/**
 * The webmention hook. While the page is live (a publish, an update) it reads the page and sends a webmention to each
 * page it links to, and to each it linked to the last time (so a removed link is heard); once it is not (an unpublish,
 * a delete, a trash), to each it last linked to, since the page is gone; on a rename, the old address too, as gone. One target failing is logged and
 * never stops the rest; a page that cannot be read fails the hook, so the store's retries run it again.
 */
export function webmentionHook(options: { store: TargetStore; fetch?: typeof fetch; userAgent?: string; log?: (entry: Record<string, unknown>) => void }): PublishHook {
  const doFetch = options.fetch ?? fetch;
  const userAgent = options.userAgent ?? "site-api webmention sender";
  const log = options.log ?? ((entry) => console.warn(JSON.stringify(entry)));

  async function send(source: string, target: string, deadline: AbortSignal): Promise<void> {
    try {
      const page = await getPage(doFetch, target, userAgent, deadline);
      const endpoint = endpointOf(page.link, page.html, page.url);
      if (!endpoint) return log({ siteApi: "webmention", source, target, result: "no endpoint" });
      if (!safeTarget(endpoint)) return log({ siteApi: "webmention", source, target, result: "refused endpoint" });
      const response = await doFetch(endpoint, {
        method: "POST",
        redirect: "manual",
        headers: { "content-type": "application/x-www-form-urlencoded", "user-agent": userAgent },
        body: new URLSearchParams({ source, target }).toString(),
        signal: limit(deadline),
      });
      await response.body?.cancel().catch(() => {});
      log({ siteApi: "webmention", source, target, result: response.ok ? "sent" : `endpoint answered ${response.status}` });
    } catch (error) {
      log({ siteApi: "webmention", source, target, result: error instanceof Error ? error.message : String(error) });
    }
  }

  async function update(source: string, gone: boolean, deadline: AbortSignal, change: string): Promise<void> {
    // Read past the edge cache: a page stored there before this write's purge lands still has the old links, and the
    // cache keys on the query, so a query of this change's own is always a fresh render.
    const fresh = new URL(source);
    fresh.searchParams.set("webmention", change);
    const links = gone ? [] : outboundLinks((await getPage(doFetch, fresh.href, userAgent, deadline)).html, source);
    const before = await options.store.webmentionTargets(source);
    const targets = [...new Set([...links, ...before])];
    if (targets.length > MAX_TARGETS) log({ siteApi: "webmention", source, result: `${targets.length} targets, the first ${MAX_TARGETS} told` });
    await Promise.all(targets.slice(0, MAX_TARGETS).map((target) => send(source, target, deadline)));
    await options.store.putWebmentionTargets(source, links, new Date().toISOString());
  }

  return {
    name: "webmention",
    on: ["publish", "update", "unpublish", "delete", "trash", "rename"],
    run: async (event) => {
      const deadline = AbortSignal.timeout(BUDGET_MS);
      const change = event.changeId ?? String(Date.now());
      if (event.previousUrl) await update(event.previousUrl, true, deadline, change);
      // A page that is not live (after an unpublish, a delete, a trash, or a save to a draft) links to nothing now.
      await update(event.url, event.status !== "published", deadline, change);
    },
  };
}

src/schedules.ts.source:
// Where a D1 site keeps the updates scheduled on its live items (v0.10.0): one table beside the site's own content
// table, so each D1 site's `schedules` adapter is a few lines over this instead of its own copy. A site that keeps its
// content elsewhere (dustinedwards.info keeps files in git) implements `SchedulesAdapter` its own way.
//
// The writes return statements, not results, so the site runs each in one `db.batch` with its own row's version move:
// the update and the item's version change together or not at all.

import type { ScheduledUpdate } from "./contract.js";

/** The part of a D1 prepared statement this uses, so a site passes its binding straight in. */
export interface D1StatementLike {
  bind(...values: unknown[]): D1StatementLike;
  first<T = Record<string, unknown>>(): Promise<T | null>;
  all<T = Record<string, unknown>>(): Promise<{ results: T[] }>;
  run(): Promise<unknown>;
}

/** The part of a D1 database binding this uses. */
export interface D1Like {
  prepare(sql: string): D1StatementLike;
}

/**
 * The migration: a D1 site adds it as its next file under `migrations/`. `publish_at` holds UTC ISO text, so the due
 * scan is a text comparison on its index.
 */
export const SCHEDULED_UPDATES_SQL = `CREATE TABLE IF NOT EXISTS scheduled_updates (
  content_id TEXT PRIMARY KEY,
  source TEXT NOT NULL,
  publish_at TEXT NOT NULL,
  change_id TEXT NOT NULL,
  scheduled_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS scheduled_updates_due ON scheduled_updates (publish_at);
`;

interface Row {
  content_id: string;
  source: string;
  publish_at: string;
  change_id: string;
  scheduled_at: string;
}

/** UTC ISO text, so every stored time compares as text and a time written with an offset matches itself. */
export function utc(time: string | Date): string {
  return new Date(time).toISOString();
}

export function d1ScheduledUpdates(db: D1Like) {
  const toUpdate = (row: Row): ScheduledUpdate => ({
    id: row.content_id,
    source: row.source,
    publishAt: row.publish_at,
    changeId: row.change_id,
    scheduledAt: row.scheduled_at,
  });

  return {
    /** The update waiting on an item, or null. */
    async get(id: string): Promise<ScheduledUpdate | null> {
      const row = await db.prepare("SELECT * FROM scheduled_updates WHERE content_id = ?").bind(id).first<Row>();
      return row ? toUpdate(row) : null;
    },
    /** Stores the update, replacing any already waiting (a reschedule). Run it in a batch with the item's version move. */
    put(id: string, input: { source: string; publishAt: string; changeId: string; scheduledAt?: Date }): D1StatementLike {
      return db
        .prepare(
          `INSERT INTO scheduled_updates (content_id, source, publish_at, change_id, scheduled_at) VALUES (?, ?, ?, ?, ?)
           ON CONFLICT (content_id) DO UPDATE SET source = excluded.source, publish_at = excluded.publish_at,
             change_id = excluded.change_id, scheduled_at = excluded.scheduled_at`,
        )
        .bind(id, input.source, utc(input.publishAt), input.changeId, utc(input.scheduledAt ?? new Date()));
    },
    /**
     * Drops the update: on a cancel, an unpublish, a publish now or a delete with no `match`; when a schedule applies,
     * with the `match` it was listed with, so a reschedule made in between is kept.
     */
    remove(id: string, match?: { publishAt: string; changeId: string }): D1StatementLike {
      return match
        ? db.prepare("DELETE FROM scheduled_updates WHERE content_id = ? AND publish_at = ? AND change_id = ?").bind(id, utc(match.publishAt), match.changeId)
        : db.prepare("DELETE FROM scheduled_updates WHERE content_id = ?").bind(id);
    },
    /** The updates due at `now`, oldest first, at most `limit`, as `SchedulesAdapter.due` lists them. */
    async due(now: Date, limit: number): Promise<Array<{ id: string; kind: "update"; publishAt: string; changeId: string }>> {
      const { results } = await db
        .prepare("SELECT content_id, publish_at, change_id FROM scheduled_updates WHERE publish_at <= ? ORDER BY publish_at, content_id LIMIT ?")
        .bind(utc(now), limit)
        .all<Row>();
      return results.map((row) => ({ id: row.content_id, kind: "update" as const, publishAt: row.publish_at, changeId: row.change_id }));
    },
  };
}

export type D1ScheduledUpdates = ReturnType<typeof d1ScheduledUpdates>;

src/store.ts.source:
// What the package keeps for itself on a site that gives it a store (v0.17.0): the answers to writes, so a retry under
// the same change id is answered rather than run twice, the publish hooks that failed, so the cron tries them again, and
// the shareable preview links and the webmentions each page last sent. A D1 site passes `d1SiteApiStore(env.DB)` as `store` and adds
// `SITE_API_STORE_SQL` as its next migration. Exported as `@dustinedwards/site-api/store`.

import type { D1Like } from "./schedules.js";

/** One write as the store holds it: claimed and running, or done with the answer it gave. */
export interface StoredWrite {
  route: string;
  requestHash: string;
  state: "running" | "done";
  status: number | null;
  response: string | null;
}

export interface SiteApiStore {
  /**
   * Claims a change id for a write about to run. Answers null when the claim is this request's: the id was free, or its
   * earlier claim was the same request and is still `running` from before `staleBefore`, so that request died before it
   * answered. Otherwise answers the row that holds the id, and claims nothing.
   */
  claimWrite(changeId: string, claim: { route: string; requestHash: string; at: string; staleBefore: string }): Promise<StoredWrite | null>;
  /** Keeps the answer the write gave, for every retry of it. */
  finishWrite(changeId: string, answer: { status: number; response: string }): Promise<void>;
  /** Drops a claim whose write failed, so a retry runs it again. */
  releaseWrite(changeId: string): Promise<void>;
  /** Drops every write claimed before `before`. */
  pruneWrites(before: string): Promise<void>;
  /** Keeps a failed hook's event for a retry at `nextAt`, replacing the row with the same id. */
  putHookRetry(retry: HookRetry): Promise<void>;
  /** The retries due at `now`, the oldest due first, at most `limit`. */
  dueHookRetries(now: string, limit: number): Promise<HookRetry[]>;
  dropHookRetry(id: string): Promise<void>;
  /** Keeps a new preview link: only the SHA-256 of its token, never the token. */
  putPreviewLink(link: PreviewLinkRow): Promise<void>;
  /** The link whose token has this hash, revoked or expired included; null when none. */
  previewLink(tokenHash: string): Promise<PreviewLinkRow | null>;
  /** One item's links not revoked and not expired at `now`, the newest first. */
  activePreviewLinks(contentId: string, now: string): Promise<PreviewLinkRow[]>;
  /** Revokes the unrevoked link whose hash starts with `prefix` (its id); false when none. */
  revokePreviewLink(prefix: string, at: string): Promise<boolean>;
  /** The targets the webmention hook last sent for a source page (v0.17.0); [] when none. */
  webmentionTargets(source: string): Promise<string[]>;
  /** Replaces a source's targets with the ones it links to now, and drops the row when there are none. */
  putWebmentionTargets(source: string, targets: string[], sentAt: string): Promise<void>;
  /**
   * v0.21.0: the media id the last upload or import with this duplicates key (duplicateKey) became; null when none. The
   * route asks it after the adapter's findByHash, so a file the site converted or shrank is still found when sent again.
   */
  uploadedMedia(sha256: string): Promise<string | null>;
  /** v0.21.0: remembers the file an upload or import with this key became, replacing an earlier one. */
  putUploadedMedia(sha256: string, mediaId: string, at: string): Promise<void>;
}

/** One shareable preview link (v0.17.0). Times are UTC ISO text; `revokedAt` null while it works. */
export interface PreviewLinkRow {
  tokenHash: string;
  contentId: string;
  createdAt: string;
  expiresAt: string;
  revokedAt: string | null;
  changeId: string;
}

/** One failed hook run, kept for another try. `event` is the PublishEvent as JSON, without its request. */
export interface HookRetry {
  id: string;
  hook: string;
  event: string;
  attempts: number;
  nextAt: string;
  lastError: string;
}

/**
 * v0.21.0's table, for a site that already applied SITE_API_STORE_SQL: it adds this as its next migration. Each row is the
 * media id an upload's duplicates key became (duplicateKey), so the same file sent again is answered with that file.
 */
export const SITE_API_STORE_SQL_V0_21 = `CREATE TABLE IF NOT EXISTS media_uploads (
  sha256 TEXT PRIMARY KEY,
  media_id TEXT NOT NULL,
  at TEXT NOT NULL
);
`;

/** The migration: a D1 site adds it as its next file under `migrations/`. Every time is UTC ISO text. */
export const SITE_API_STORE_SQL = `CREATE TABLE IF NOT EXISTS site_api_writes (
  change_id TEXT PRIMARY KEY,
  route TEXT NOT NULL,
  request_hash TEXT NOT NULL,
  status INTEGER,
  response TEXT,
  state TEXT NOT NULL,
  at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS site_api_writes_at ON site_api_writes (at);
CREATE TABLE IF NOT EXISTS hook_retries (
  id TEXT PRIMARY KEY,
  hook TEXT NOT NULL,
  event TEXT NOT NULL,
  attempts INTEGER NOT NULL,
  next_at TEXT NOT NULL,
  last_error TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS hook_retries_due ON hook_retries (next_at);
CREATE TABLE IF NOT EXISTS preview_links (
  token_hash TEXT PRIMARY KEY,
  content_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  revoked_at TEXT,
  change_id TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS preview_links_content ON preview_links (content_id, expires_at);
CREATE TABLE IF NOT EXISTS webmention_targets (
  source TEXT PRIMARY KEY,
  targets TEXT NOT NULL,
  sent_at TEXT NOT NULL
);
${SITE_API_STORE_SQL_V0_21}`;

interface WriteRow {
  route: string;
  request_hash: string;
  state: "running" | "done";
  status: number | null;
  response: string | null;
}

interface LinkRow {
  token_hash: string;
  content_id: string;
  created_at: string;
  expires_at: string;
  revoked_at: string | null;
  change_id: string;
}

const toLink = (r: LinkRow): PreviewLinkRow => ({
  tokenHash: r.token_hash,
  contentId: r.content_id,
  createdAt: r.created_at,
  expiresAt: r.expires_at,
  revokedAt: r.revoked_at,
  changeId: r.change_id,
});

export function d1SiteApiStore(db: D1Like): SiteApiStore {
  const claimWrite: SiteApiStore["claimWrite"] = async (changeId, claim) => {
    // One statement, so two requests racing for an id cannot both win: the insert, or the takeover of the same
    // request's stale claim, returns the row only when it was this request's.
    const won = await db
      .prepare(
        `INSERT INTO site_api_writes (change_id, route, request_hash, status, response, state, at) VALUES (?, ?, ?, NULL, NULL, 'running', ?)
         ON CONFLICT (change_id) DO UPDATE SET at = excluded.at
         WHERE site_api_writes.state = 'running' AND site_api_writes.at < ?
           AND site_api_writes.route = excluded.route AND site_api_writes.request_hash = excluded.request_hash
         RETURNING change_id`,
      )
      .bind(changeId, claim.route, claim.requestHash, claim.at, claim.staleBefore)
      .first();
    if (won) return null;
    const row = await db.prepare("SELECT route, request_hash, state, status, response FROM site_api_writes WHERE change_id = ?").bind(changeId).first<WriteRow>();
    // Released between the two statements: the id is free again, so claim it once more.
    if (!row) return claimWrite(changeId, claim);
    return { route: row.route, requestHash: row.request_hash, state: row.state, status: row.status, response: row.response };
  };

  return {
    claimWrite,
    async finishWrite(changeId, answer) {
      await db.prepare("UPDATE site_api_writes SET state = 'done', status = ?, response = ? WHERE change_id = ?").bind(answer.status, answer.response, changeId).run();
    },
    async releaseWrite(changeId) {
      await db.prepare("DELETE FROM site_api_writes WHERE change_id = ? AND state = 'running'").bind(changeId).run();
    },
    async pruneWrites(before) {
      await db.prepare("DELETE FROM site_api_writes WHERE at < ?").bind(before).run();
    },
    async putHookRetry(r) {
      await db
        .prepare(
          `INSERT INTO hook_retries (id, hook, event, attempts, next_at, last_error) VALUES (?, ?, ?, ?, ?, ?)
           ON CONFLICT (id) DO UPDATE SET attempts = excluded.attempts, next_at = excluded.next_at, last_error = excluded.last_error`,
        )
        .bind(r.id, r.hook, r.event, r.attempts, r.nextAt, r.lastError)
        .run();
    },
    async dueHookRetries(now, limit) {
      const { results } = await db
        .prepare("SELECT id, hook, event, attempts, next_at, last_error FROM hook_retries WHERE next_at <= ? ORDER BY next_at, id LIMIT ?")
        .bind(now, limit)
        .all<{ id: string; hook: string; event: string; attempts: number; next_at: string; last_error: string }>();
      return results.map((r) => ({ id: r.id, hook: r.hook, event: r.event, attempts: r.attempts, nextAt: r.next_at, lastError: r.last_error }));
    },
    async dropHookRetry(id) {
      await db.prepare("DELETE FROM hook_retries WHERE id = ?").bind(id).run();
    },
    async putPreviewLink(l) {
      await db
        .prepare("INSERT INTO preview_links (token_hash, content_id, created_at, expires_at, revoked_at, change_id) VALUES (?, ?, ?, ?, ?, ?)")
        .bind(l.tokenHash, l.contentId, l.createdAt, l.expiresAt, l.revokedAt, l.changeId)
        .run();
    },
    async previewLink(tokenHash) {
      const row = await db.prepare("SELECT * FROM preview_links WHERE token_hash = ?").bind(tokenHash).first<LinkRow>();
      return row ? toLink(row) : null;
    },
    async activePreviewLinks(contentId, now) {
      const { results } = await db
        .prepare("SELECT * FROM preview_links WHERE content_id = ? AND revoked_at IS NULL AND expires_at > ? ORDER BY created_at DESC")
        .bind(contentId, now)
        .all<LinkRow>();
      return results.map(toLink);
    },
    async revokePreviewLink(prefix, at) {
      // The prefix is hex the package checked, so it is safe inside LIKE.
      const row = await db
        .prepare("UPDATE preview_links SET revoked_at = ? WHERE token_hash LIKE ? AND revoked_at IS NULL RETURNING token_hash")
        .bind(at, `${prefix}%`)
        .first();
      return row !== null;
    },
    async webmentionTargets(source) {
      const row = await db.prepare("SELECT targets FROM webmention_targets WHERE source = ?").bind(source).first<{ targets: string }>();
      return row ? (JSON.parse(row.targets) as string[]) : [];
    },
    async putWebmentionTargets(source, targets, sentAt) {
      await (targets.length === 0
        ? db.prepare("DELETE FROM webmention_targets WHERE source = ?").bind(source)
        : db
            .prepare("INSERT INTO webmention_targets (source, targets, sent_at) VALUES (?, ?, ?) ON CONFLICT (source) DO UPDATE SET targets = excluded.targets, sent_at = excluded.sent_at")
            .bind(source, JSON.stringify(targets), sentAt)
      ).run();
    },
    async uploadedMedia(sha256) {
      const row = await db.prepare("SELECT media_id FROM media_uploads WHERE sha256 = ?").bind(sha256).first<{ media_id: string }>();
      return row?.media_id ?? null;
    },
    async putUploadedMedia(sha256, mediaId, at) {
      await db
        .prepare("INSERT INTO media_uploads (sha256, media_id, at) VALUES (?, ?, ?) ON CONFLICT (sha256) DO UPDATE SET media_id = excluded.media_id, at = excluded.at")
        .bind(sha256, mediaId, at)
        .run();
    },
  };
}

src/local.ts.source:
// A site's own admin, talking to its own adapter in process. localClient(adapter) answers every
// method createSiteClient does, with the same types and the same SiteApiError, by handing each
// request straight to createSiteApi's handler: no network, no configured key, and the very code
// Carrel's requests meet. So every route rule, version check, upload check and zod parse is the one
// Carrel gets, and the content kit (./admin) runs the same against either client.

import { toHex } from "@dustinedwards/site-runtime/encoding";
import type { SiteAdapter } from "./adapter.js";
import { createSiteClient, type SiteClient } from "./client.js";
import { createSiteApi } from "./server.js";

export interface LocalClientOptions {
  /** Where adapter failures and contract breaches are logged. Defaults to console, as createSiteApi does. */
  log?: (entry: Record<string, unknown>) => void;
}

/** A key that lives only in this closure: the handler insists on one, and nothing outside can learn it. */
function inProcessKey(): string {
  return toHex(crypto.getRandomValues(new Uint8Array(32)));
}

export function localClient(adapter: SiteAdapter, options: LocalClientOptions = {}): SiteClient {
  const key = inProcessKey();
  const api = createSiteApi({
    adapter,
    key,
    // One person in their own admin is not a burst from the internet; the site's own sign-in guards this door.
    limiter: { limit: async () => ({ success: true }) },
    ...(options.log ? { log: options.log } : {}),
  });
  const handle = (async (input: RequestInfo | URL, init?: RequestInit) => api.handle(new Request(input, init))) as typeof fetch;
  return createSiteClient({ baseUrl: adapter.site.origin, key, fetch: handle });
}

src/server/content.ts.source:
// The meta route, the content routes and the preview: what every site serves.

import { createTwoFilesPatch } from "diff";
import { capabilitiesOf, contentFiltersOf, hasContentTrash, NotFoundError, RefusedError, VersionConflictError, type SiteAdapter } from "../adapter.js";
import {
  ContentDeleteQuery,
  ContentDeleteResult,
  ContentDoc,
  ContentId,
  ContentList,
  ContentTagsInput,
  ContentTrashInput,
  Diff,
  DiffQuery,
  ListQuery,
  Meta,
  PACKAGE_VERSION,
  PreviewInput,
  PublishInput,
  RenameInput,
  RenameResult,
  RevisionList,
  RevisionSource,
  SaveDraftInput,
  ScheduleCancelQuery,
  ScheduleInput,
  ScheduledUpdate,
  UnpublishInput,
  Version,
  WriteResult,
  schemaHash,
  filtersAsked,
} from "../contract.js";
import { BadRequest, BASE_HEADERS, ContractBreach, ID, checked, fail, json, pathParam, readBody, readQuery, type Route } from "./http.js";

export function contentRoutes(adapter: SiteAdapter, options: { store: boolean }): Route[] {
  const id = (m: RegExpMatchArray) => pathParam(m[1], ContentId, "content id");

  const write = async (
    m: RegExpMatchArray,
    request: Request,
    run: (contentId: string, request: Request) => Promise<unknown>,
  ) => json(200, checked(WriteResult, await run(id(m), request), "write result"));

  return [
    {
      method: "GET",
      pattern: /^\/meta$/,
      run: async () =>
        json(200, checked(Meta, {
          api: "carrel-site-api",
          packageVersion: PACKAGE_VERSION,
          schemaHash: await schemaHash(),
          site: adapter.site,
          capabilities: capabilitiesOf(adapter, options),
        }, "meta")),
    },
    {
      method: "GET",
      pattern: /^\/content$/,
      run: async (_m, url) => {
        const query = readQuery(url, ListQuery);
        const offered = contentFiltersOf(adapter);
        const asked = filtersAsked(query);
        const missing = asked.find((f) => !offered.includes(f));
        if (missing) return fail("not-implemented", `This site does not filter its content list by ${missing}.`);
        const list = checked(ContentList, await adapter.content.list(query), "content list");
        return json(200, asked.length ? { ...list, filtered: asked } : list);
      },
    },
    {
      method: "GET",
      pattern: new RegExp(`^/content/${ID}$`),
      run: async (m) => {
        const doc = await adapter.content.get(id(m));
        if (!doc) throw new NotFoundError();
        return json(200, checked(ContentDoc, doc, "content"));
      },
    },
    {
      method: "PUT",
      pattern: new RegExp(`^/content/${ID}/draft$`),
      run: (m, _u, r) => write(m, r, async (i, req) => adapter.content.saveDraft(i, await readBody(req, SaveDraftInput))),
    },
    {
      method: "POST",
      pattern: new RegExp(`^/content/${ID}/publish$`),
      run: (m, _u, r) =>
        write(m, r, async (i, req) => {
          const input = await readBody(req, PublishInput);
          if (input.publishedAt !== undefined) {
            if (!adapter.content.publishedAtSettable) throw new BadRequest("not-implemented", "This site does not set the date a post is published under.");
            // A minute's grace for the caller's clock; a later date is a schedule, which says when the post goes live.
            if (Date.parse(input.publishedAt) > Date.now() + 60_000) throw new BadRequest("invalid", "publishedAt is in the future. To publish later, schedule it.");
          }
          return adapter.content.publish(i, input);
        }),
    },
    {
      method: "POST",
      pattern: new RegExp(`^/content/${ID}/schedule$`),
      run: (m, _u, r) =>
        write(m, r, async (i, req) => {
          const input = await readBody(req, ScheduleInput);
          const current = await adapter.content.get(i);
          // v0.10.0: a live item keeps being served, and the schedule is an update that replaces it at the time.
          if (current?.status !== "published") return adapter.content.schedule(i, input);
          if (current.version !== input.expectedVersion) throw new VersionConflictError(current.version);
          if (!adapter.schedules) {
            throw new RefusedError("This site cannot schedule an update to a live post: scheduling it would take the post off the site until then. Publish the change now, or unpublish first.");
          }
          const { publishAt, expectedVersion, changeId } = input;
          return adapter.schedules.update(i, { source: input.source ?? current.source, publishAt, expectedVersion, changeId });
        }),
    },
    {
      method: "GET",
      pattern: new RegExp(`^/content/${ID}/schedule$`),
      run: async (m) => {
        const contentId = id(m);
        if (!adapter.schedules) return fail("not-implemented", "This site does not schedule updates to live posts.");
        const update = await adapter.schedules.get(contentId);
        if (!update) throw new NotFoundError("Nothing is scheduled for this item.");
        return json(200, checked(ScheduledUpdate, update, "scheduled update"));
      },
    },
    {
      method: "DELETE",
      pattern: new RegExp(`^/content/${ID}/schedule$`),
      run: async (m, url) => {
        const contentId = id(m);
        if (!adapter.schedules) return fail("not-implemented", "This site does not schedule updates to live posts.");
        return json(200, checked(WriteResult, await adapter.schedules.cancel(contentId, readQuery(url, ScheduleCancelQuery)), "schedule cancel"));
      },
    },
    {
      method: "POST",
      pattern: new RegExp(`^/content/${ID}/unpublish$`),
      run: (m, _u, r) => write(m, r, async (i, req) => adapter.content.unpublish(i, await readBody(req, UnpublishInput))),
    },
    {
      method: "GET",
      pattern: new RegExp(`^/content/${ID}/revisions$`),
      run: async (m) => {
        const items = await adapter.content.revisions(id(m));
        if (!items) throw new NotFoundError();
        return json(200, checked(RevisionList, { items }, "revisions"));
      },
    },
    {
      method: "GET",
      pattern: new RegExp(`^/content/${ID}/revisions/${ID}$`),
      run: async (m) => {
        const contentId = id(m);
        const version = pathParam(m[2], Version, "version");
        const source = await adapter.content.revisionSource(contentId, version);
        if (source === null) throw new NotFoundError("No such version.");
        return json(200, checked(RevisionSource, { id: contentId, version, source }, "revision source"));
      },
    },
    {
      method: "DELETE",
      pattern: new RegExp(`^/content/${ID}$`),
      run: async (m, url) => {
        const contentId = id(m);
        // A site with no delete answers 501 whatever the query says.
        if (!adapter.content.delete) return fail("not-implemented", "This site does not delete content through the API.");
        const query = readQuery(url, ContentDeleteQuery);
        await adapter.content.delete(contentId, query);
        return json(200, checked(ContentDeleteResult, { id: contentId, deleted: true, changeId: query.changeId }, "content delete"));
      },
    },
    {
      method: "PUT",
      pattern: new RegExp(`^/content/${ID}/tags$`),
      run: async (m, _u, request) => {
        const contentId = id(m);
        if (!adapter.content.setTags) return fail("not-implemented", "This site does not keep tags on posts through the API.");
        const input = await readBody(request, ContentTagsInput);
        // One spelling per tag: the first one given wins, so "News" and "news" are one tag.
        const seen = new Set<string>();
        const tags = input.tags.filter((t) => !seen.has(t.toLowerCase()) && seen.add(t.toLowerCase()));
        return json(200, checked(WriteResult, await adapter.content.setTags(contentId, { ...input, tags }), "content tags"));
      },
    },
    {
      method: "POST",
      pattern: new RegExp(`^/content/${ID}/rename$`),
      run: async (m, _u, request) => {
        const contentId = id(m);
        if (!adapter.content.rename) return fail("not-implemented", "This site does not rename content through the API.");
        const input = await readBody(request, RenameInput);
        if (input.newId === contentId) throw new BadRequest("invalid", "newId is the item's own id.");
        return json(200, checked(RenameResult, await adapter.content.rename(contentId, input), "content rename"));
      },
    },
    ...(["trash", "restore"] as const).map((op) => ({
      method: "POST",
      pattern: new RegExp(`^/content/${ID}/${op}$`),
      run: async (m: RegExpMatchArray, _u: URL, request: Request) => {
        const contentId = id(m);
        if (!hasContentTrash(adapter)) return fail("not-implemented", "This site has no content trash.");
        const input = await readBody(request, ContentTrashInput);
        return json(200, checked(WriteResult, await adapter.content[op]!(contentId, input), `content ${op}`));
      },
    })),
    {
      method: "GET",
      pattern: new RegExp(`^/content/${ID}/diff$`),
      run: async (m, url) => {
        const contentId = id(m);
        const query = readQuery(url, DiffQuery);
        const current = await adapter.content.get(contentId);
        if (!current) throw new NotFoundError();
        const to = query.to ?? current.version;
        const [before, after] = await Promise.all([
          adapter.content.revisionSource(contentId, query.from),
          to === current.version ? current.source : adapter.content.revisionSource(contentId, to),
        ]);
        if (before === null || after === null) throw new NotFoundError("No such version.");
        const patch = createTwoFilesPatch(`${contentId}@${query.from}`, `${contentId}@${to}`, before, after);
        return json(200, checked(Diff, { id: contentId, from: query.from, to, patch }, "diff"));
      },
    },
    {
      method: "POST",
      pattern: /^\/preview$/,
      run: async (_m, _u, request) => {
        const html = await adapter.preview.render(await readBody(request, PreviewInput));
        if (typeof html !== "string") throw new ContractBreach("preview: not a string");
        return new Response(html, {
          status: 200,
          // v0.17.0: a preview is never a page to index, whatever the site's own render says.
          headers: { ...BASE_HEADERS, "content-type": "text/html; charset=utf-8", "x-robots-tag": "noindex, nofollow" },
        });
      },
    },
  ];
}

